r = trim ( tecHeader ) // ', \"d/dy(' // trim ( this % solution % meta ( iVar )% name ) // ')\"' enddo do iVar = 1 , this % solution % nVar tecHeader = trim ( tecHeader ) // ', \"d/dt(' // trim ( this % solution % meta ( iVar )% name ) // ')\"' enddo write ( fUnit , * ) trim ( tecHeader ) ! Create format statement write ( fmat , * ) 4 * this % solution % nvar + 2 fmat = '(' // trim ( fmat ) // '(ES16.7E3,1x))' do iEl = 1 , this % solution % nElem ! TO DO :: Get the global element ID write ( zoneID , '(I8.8)' ) iEl write ( fUnit , * ) 'ZONE T=\"el' // trim ( zoneID ) // '\", I=' , this % solution % interp % M + 1 , & ', J=' , this % solution % interp % M + 1 do j = 1 , this % solution % interp % M + 1 do i = 1 , this % solution % interp % M + 1 write ( fUnit , fmat ) x % interior ( i , j , iEl , 1 , 1 ), & x % interior ( i , j , iEl , 1 , 2 ), & solution % interior ( i , j , iEl , 1 : this % solution % nvar ), & solutionGradient % interior ( i , j , iEl , 1 : this % solution % nvar , 1 ), & solutionGradient % interior ( i , j , iEl , 1 : this % solution % nvar , 2 ), & dsdt % interior ( i , j , iEl , 1 : this % solution % nvar ) enddo enddo enddo close ( UNIT = fUnit ) call x % Free () call solution % Free () call dsdt % Free () call interp % Free () endsubroutine WriteTecplot_DGModel2D_t","tags":"","loc":"proc/writetecplot_dgmodel2d_t.html"},{"title":"Write_DGModel2D_t – SELF","text":"public subroutine Write_DGModel2D_t(this, fileName) Arguments Type Intent Optional Attributes Name class( DGModel2D_t ), intent(inout) :: this character, intent(in), optional :: fileName Calls proc~~write_dgmodel2d_t~~CallsGraph proc~write_dgmodel2d_t Write_DGModel2D_t interface~open_hdf5 Open_HDF5 proc~write_dgmodel2d_t->interface~open_hdf5 proc~close_hdf5 Close_HDF5 proc~write_dgmodel2d_t->proc~close_hdf5 proc~creategroup_hdf5 CreateGroup_HDF5 proc~write_dgmodel2d_t->proc~creategroup_hdf5 proc~open_hdf5_serial Open_HDF5_serial interface~open_hdf5->proc~open_hdf5_serial proc~open_hdf5