/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////// ! ! ! Maintainers : support@fluidnumerics.com ! Official Repository : https://github.com/FluidNumerics/self/ ! ! Copyright © 2024 Fluid Numerics LLC ! ! Redistribution and use in source and binary forms, with or without modification, are permitted provided that the following conditions are met: ! ! 1. Redistributions of source code must retain the above copyright notice, this list of conditions and the following disclaimer. ! ! 2. Redistributions in binary form must reproduce the above copyright notice, this list of conditions and the following disclaimer in !    the documentation and/or other materials provided with the distribution. ! ! 3. Neither the name of the copyright holder nor the names of its contributors may be used to endorse or promote products derived from !    this software without specific prior written permission. ! ! THIS SOFTWARE IS PROVIDED BY THE COPYRIGHT HOLDERS AND CONTRIBUTORS “AS IS” AND ANY EXPRESS OR IMPLIED WARRANTIES, INCLUDING, BUT NOT ! LIMITED TO, THE IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE ARE DISCLAIMED. IN NO EVENT SHALL THE COPYRIGHT ! HOLDER OR CONTRIBUTORS BE LIABLE FOR ANY DIRECT, INDIRECT, INCIDENTAL, SPECIAL, EXEMPLARY, OR CONSEQUENTIAL DAMAGES (INCLUDING, BUT NOT ! LIMITED TO, PROCUREMENT OF SUBSTITUTE GOODS OR SERVICES; LOSS OF USE, DATA, OR PROFITS; OR BUSINESS INTERRUPTION) HOWEVER CAUSED AND ON ANY ! THEORY OF LIABILITY, WHETHER IN CONTRACT, STRICT LIABILITY, OR TORT (INCLUDING NEGLIGENCE OR OTHERWISE) ARISING IN ANY WAY OUT OF THE USE OF ! THIS SOFTWARE, EVEN IF ADVISED OF THE POSSIBILITY OF SUCH DAMAGE. ! ! //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////// ! module SELF_Scalar_1D use SELF_Constants use SELF_Scalar_1D_t use SELF_GPU use SELF_GPUBLAS use iso_c_binding implicit none ! ---------------------- Scalars ---------------------- ! type , extends ( Scalar1D_t ), public :: Scalar1D character ( 3 ) :: backend = \"apu\" type ( c_ptr ) :: blas_handle contains procedure , public :: Init => Init_Scalar1D procedure , public :: Free => Free_Scalar1D procedure , public :: BoundaryInterp => BoundaryInterp_Scalar1D !procedure,public :: GridInterp => GridInterp_Scalar1D !procedure,public :: Derivative => Derivative_Scalar1D endtype Scalar1D contains ! -- Scalar1D -- ! subroutine Init_Scalar1D ( this , interp , nVar , nElem ) implicit none class ( Scalar1D ), intent ( out ) :: this type ( Lagrange ), intent ( in ), target :: interp integer , intent ( in ) :: nVar integer , intent ( in ) :: nElem if (. not . GPUAvailable ()) then print * , __ FILE__ , ':' , __ LINE__ , ' : Error : Attempt to use GPU extension, but GPU is not available.' stop 1 endif this % interp => interp this % nVar = nVar this % nElem = nElem this % N = interp % N this % M = interp % M allocate ( this % interior ( 1 : interp % N + 1 , 1 : nelem , 1 : nvar ), & this % boundary ( 1 : 2 , 1 : nelem , 1 : nvar ), & this % extBoundary ( 1 : 2 , 1 : nelem , 1 : nvar ), & this % avgBoundary ( 1 : 2 , 1 : nelem , 1 : nvar )) allocate ( this % meta ( 1 : nVar )) allocate ( this % eqn ( 1 : nVar )) call gpuCheck ( hipMalloc ( c_loc ( this % interior_gpu ), sizeof ( this % interior ))) call gpuCheck ( hipMalloc ( c_loc ( this % boundary_gpu ), sizeof ( this % boundary ))) call gpuCheck ( hipMalloc ( c_loc ( this % extBoundary_gpu ), sizeof ( this % extBoundary ))) call gpuCheck ( hipMalloc ( c_loc ( this % avgBoundary_gpu ), sizeof ( this % avgBoundary ))) call hipblasCheck ( hipblasCreate ( this % blas_handle )) endsubroutine Init_Scalar1D subroutine Free_Scalar1D ( this ) implicit none class ( Scalar1D ), intent ( inout ) :: this this % interp => null () deallocate ( this % interior ) deallocate ( this % boundary ) deallocate ( this % extBoundary ) deallocate ( this % meta ) deallocate